def longest_run(values):
    if not values:
        return 0
    max_run = 1
    current_run = 1
    for i in range(1, len(values)):
        if values[i] == values[i-1]:
            current_run += 1
        else:
            current_run = 1
        if current_run > max_run:
            max_run = current_run
    return max_run
